$e=@();[xml]$p=Get-Content pom.xml -Raw;$mods=@($p.project.modules.module);$dirs=@(Get-ChildItem labs,projects -Directory|Sort-Object FullName);$expected=@($dirs|%{$_.FullName.Substring((Get-Location).Path.Length+1).Replace("\", "/")});if(($mods-join ",")-ne($expected-join ",")){$e+="module order"}
$heads=@("## Overview","## Learning Objectives","## Prerequisites","## What You Will Build","## Concepts Covered","## Project Structure","## Running the Lab","## Exercises","## Acceptance Criteria","## Tests","## Common Pitfalls","## Further Exploration","## Next Lesson");foreach($d in $dirs){$r=Join-Path $d.FullName "README.md";if(!(Test-Path $r)-or!(Test-Path(Join-Path $d.FullName "pom.xml"))){$e+="$d missing README or pom"};if($d.FullName -match "labs\\"){$t=Get-Content $r -Raw;foreach($h in $heads){if($t.IndexOf($h)-lt 0){$e+="$d missing $h"}}}}
if(Get-ChildItem labs,projects -Recurse -File -Include *.java,*.xml|Select-String "com\.studyforge"){$e+="com.studyforge remains in reactor"};if($e){$e|%{Write-Error $_};exit 1};Write-Output "Curriculum validation passed."
